#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    vector<string> g(n);
    for (auto &row : g) cin >> row;
    int dx[4] = {-1, 1, 0, 0}, dy[4] = {0, 0, -1, 1};
    // State: cell plus lock (0..3 = locked direction, 4 = free).
    auto id = [&](int x, int y, int lock) { return (x * m + y) * 5 + lock; };
    vector<int> dist(n * m * 5, -1);
    deque<int> q;
    for (int i = 0; i < n; i++)
        for (int j = 0; j < m; j++)
            if (g[i][j] == 'S') {
                dist[id(i, j, 4)] = 0;
                q.push_back(id(i, j, 4));
            }
    while (!q.empty()) {
        int s = q.front();
        q.pop_front();
        int lock = s % 5, cell = s / 5, x = cell / m, y = cell % m;
        if (g[x][y] == 'E' && lock == 4) {
            printf("%d\n", dist[s]);
            return 0;
        }
        for (int d = 0; d < 4; d++) {
            if (lock != 4 && d != lock) continue;
            int a = x + dx[d], b = y + dy[d], len = 1;
            // Jumps may pass over walls but cannot land on them.
            for (; a >= 0 && a < n && b >= 0 && b < m; a += dx[d], b += dy[d], len++) {
                if (g[a][b] == '#') continue;
                int t = id(a, b, len == 1 ? 4 : d);
                if (dist[t] < 0) {
                    dist[t] = dist[s] + 1;
                    q.push_back(t);
                }
            }
        }
    }
    puts("-1");
}

import java.io.*;

public class Main {
    static byte[] buf;
    static int pos;

    static void skip() {
        while (pos < buf.length && buf[pos] <= ' ') pos++;
    }

    static String next() {
        skip();
        int s = pos;
        while (pos < buf.length && buf[pos] > ' ') pos++;
        return new String(buf, s, pos - s);
    }

    static long nextLong() {
        skip();
        boolean neg = buf[pos] == '-';
        if (neg) pos++;
        long r = 0;
        while (pos < buf.length && buf[pos] > ' ') r = r * 10 + (buf[pos++] - '0');
        return neg ? -r : r;
    }

    static int nextInt() {
        return (int) nextLong();
    }

    public static void main(String[] args) throws IOException {
        buf = System.in.readAllBytes();
        int n = nextInt(), m = nextInt();
        char[][] g = new char[n][];
        for (int i = 0; i < n; i++) g[i] = next().toCharArray();
        int[] dx = {-1, 1, 0, 0}, dy = {0, 0, -1, 1};
        // State: (x*m+y)*5+lock, lock 0..3 = locked direction, 4 = free.
        int[] dist = new int[n * m * 5];
        java.util.Arrays.fill(dist, -1);
        int[] q = new int[n * m * 5];
        int head = 0, tail = 0;
        for (int i = 0; i < n; i++)
            for (int j = 0; j < m; j++)
                if (g[i][j] == 'S') {
                    int s = (i * m + j) * 5 + 4;
                    dist[s] = 0;
                    q[tail++] = s;
                }
        while (head < tail) {
            int s = q[head++];
            int lock = s % 5, cell = s / 5, x = cell / m, y = cell % m;
            if (g[x][y] == 'E' && lock == 4) {
                System.out.println(dist[s]);
                return;
            }
            for (int d = 0; d < 4; d++) {
                if (lock != 4 && d != lock) continue;
                int a = x + dx[d], b = y + dy[d], len = 1;
                // Jumps may pass over walls but cannot land on them.
                for (; a >= 0 && a < n && b >= 0 && b < m; a += dx[d], b += dy[d], len++) {
                    if (g[a][b] == '#') continue;
                    int t = (a * m + b) * 5 + (len == 1 ? 4 : d);
                    if (dist[t] < 0) {
                        dist[t] = dist[s] + 1;
                        q[tail++] = t;
                    }
                }
            }
        }
        System.out.println(-1);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var p int

func next() []byte {
	for p < len(data) && data[p] <= ' ' {
		p++
	}
	s := p
	for p < len(data) && data[p] > ' ' {
		p++
	}
	return data[s:p]
}

func nextInt() int64 {
	t := next()
	neg := len(t) > 0 && t[0] == '-'
	if neg {
		t = t[1:]
	}
	var r int64
	for _, c := range t {
		r = r*10 + int64(c-'0')
	}
	if neg {
		return -r
	}
	return r
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n, m := int(nextInt()), int(nextInt())
	g := make([][]byte, n)
	for i := range g {
		g[i] = next()
	}
	dx, dy := [4]int{-1, 1, 0, 0}, [4]int{0, 0, -1, 1}
	// State: (x*m+y)*5+lock, lock 0..3 = locked direction, 4 = free.
	dist := make([]int, n*m*5)
	for i := range dist {
		dist[i] = -1
	}
	q := make([]int, 0, n*m*5)
	for i := 0; i < n; i++ {
		for j := 0; j < m; j++ {
			if g[i][j] == 'S' {
				s := (i*m+j)*5 + 4
				dist[s] = 0
				q = append(q, s)
			}
		}
	}
	for h := 0; h < len(q); h++ {
		s := q[h]
		lock, cell := s%5, s/5
		x, y := cell/m, cell%m
		if g[x][y] == 'E' && lock == 4 {
			fmt.Println(dist[s])
			return
		}
		for d := 0; d < 4; d++ {
			if lock != 4 && d != lock {
				continue
			}
			// Jumps may pass over walls but cannot land on them.
			for a, b, l := x+dx[d], y+dy[d], 1; a >= 0 && a < n && b >= 0 && b < m; a, b, l = a+dx[d], b+dy[d], l+1 {
				if g[a][b] == '#' {
					continue
				}
				nl := d
				if l == 1 {
					nl = 4
				}
				t := (a*m+b)*5 + nl
				if dist[t] < 0 {
					dist[t] = dist[s] + 1
					q = append(q, t)
				}
			}
		}
	}
	fmt.Println(-1)
}
